'use client';

import { useEffect, useState } from 'react';

export interface FontToCheck {
  key: string;
  /** First family name as generated by next/font. */
  family: string;
}

interface Result {
  rupee: boolean;
  tabular: boolean;
  proportionalDefault: boolean;
  devanagari: boolean;
  tamil: boolean;
}

function width(text: string, fontFamily: string, extra: Record<string, string> = {}): number {
  const span = document.createElement('span');
  span.textContent = text;
  Object.assign(span.style, {
    position: 'absolute',
    visibility: 'hidden',
    whiteSpace: 'nowrap',
    fontSize: '40px',
    fontFamily,
    ...extra,
  });
  document.body.appendChild(span);
  const w = span.getBoundingClientRect().width;
  span.remove();
  return w;
}

/**
 * A glyph is native when two different fallbacks that both contain it produce the same width.
 * (Generic `serif`/`monospace` cannot be used for Indic scripts: neither has the glyphs, so both
 * fall through to the same system font and every font would wrongly "pass".)
 */
function hasGlyphs(family: string, sample: string, fallbackA: string, fallbackB: string): boolean {
  const a = width(sample, `${family}, ${fallbackA}`);
  const b = width(sample, `${family}, ${fallbackB}`);
  return Math.abs(a - b) < 0.5;
}

export interface Probes {
  devanagari: [string, string];
  tamil: [string, string];
}

const DEVANAGARI = 'अनन्या मिश्रा';
const TAMIL = 'செல்வி ராஜன்';

async function check(family: string, probes: Probes): Promise<Result> {
  const loads = [
    document.fonts.load(`40px ${family}`, '₹0123456789'),
    document.fonts.load(`40px ${family}`, DEVANAGARI),
    document.fonts.load(`40px ${family}`, TAMIL),
    ...probes.devanagari.map((f) => document.fonts.load(`40px ${f}`, DEVANAGARI)),
    ...probes.tamil.map((f) => document.fonts.load(`40px ${f}`, TAMIL)),
  ];
  await Promise.all(loads);
  const tab = { fontVariantNumeric: 'tabular-nums' };
  const ones = width('1111111111', family, tab);
  const zeros = width('0000000000', family, tab);
  return {
    rupee: hasGlyphs(family, '₹₹₹₹₹', 'monospace', 'serif'),
    tabular: Math.abs(ones - zeros) < 0.5,
    proportionalDefault: Math.abs(width('1111111111', family) - width('0000000000', family)) >= 0.5,
    devanagari: hasGlyphs(family, DEVANAGARI, probes.devanagari[0], probes.devanagari[1]),
    tamil: hasGlyphs(family, TAMIL, probes.tamil[0], probes.tamil[1]),
  };
}

function Mark({ ok, yes, no }: { ok: boolean | undefined; yes: string; no: string }) {
  if (ok === undefined) return <span className="text-ink-3">Measuring…</span>;
  return (
    <span className={ok ? 'text-verified' : 'text-attention'}>
      <span aria-hidden="true">{ok ? '✓ ' : '– '}</span>
      {ok ? yes : no}
    </span>
  );
}

export function FontChecks({
  fonts,
  indicFallback,
  probes,
}: {
  fonts: FontToCheck[];
  indicFallback: string;
  probes: Probes;
}) {
  const [results, setResults] = useState<Record<string, Result>>({});

  useEffect(() => {
    let cancelled = false;
    void Promise.all(fonts.map(async (f) => [f.key, await check(f.family, probes)] as const)).then(
      (entries) => {
        if (!cancelled) setResults(Object.fromEntries(entries));
      },
    );
    return () => {
      cancelled = true;
    };
  }, [fonts, probes]);

  return (
    <dl
      className="grid gap-x-6 gap-y-1.5 text-[13px] sm:grid-cols-[auto_1fr]"
      data-testid="font-checks"
    >
      {fonts.map((f) => {
        const r = results[f.key];
        return (
          <div key={f.key} className="contents">
            <dt className="font-medium text-ink">{f.key}</dt>
            <dd
              className="flex flex-wrap gap-x-4 gap-y-0.5"
              data-font={f.key}
              data-measured={r ? 'true' : 'false'}
            >
              <Mark ok={r?.rupee} yes="Native ₹ glyph" no="₹ falls back to another font" />
              <Mark ok={r?.tabular} yes="Tabular figures" no="No tabular figures" />
              {r ? (
                <span className="text-ink-3">
                  {r.proportionalDefault ? 'Proportional by default' : 'Tabular by default'}
                </span>
              ) : null}
              <Mark
                ok={r?.devanagari}
                yes="Devanagari built in"
                no={`Devanagari via ${indicFallback}`}
              />
              <Mark ok={r?.tamil} yes="Tamil built in" no={`Tamil via ${indicFallback}`} />
            </dd>
          </div>
        );
      })}
    </dl>
  );
}
